		entry = &cache->entries[entry_index];
		if ( (entry->flags & SPARK_KV_PAGE_CACHE_ENTRY_FLAG_VALID) != 0u &&
			entry->token_count == token_count &&
			memcmp(&entry->identity,identity,sizeof(*identity)) == 0 )
