	entry = &cache->entries[entry_index];
	bucket = SparkKvPageCacheBucket(cache,&entry->identity,entry->token_count);
	link = &cache->hash_bucket_heads[bucket];
	while ( *link != SPARK_KV_PAGE_CACHE_NO_INDEX )
	{
		if ( *link == entry_index )
		{
			*link = entry->hash_next;
			return;
