	for (index=0u; index<sizeof(identity->sha256); index++)
	{
		hash ^= identity->sha256[index];
		hash *= UINT64_C(1099511628211);
	}
	hash ^= token_count;
	hash *= UINT64_C(1099511628211);
	hash ^= hash >> 33u;
	hash *= UINT64_C(0xff51afd7ed558ccd);
	return(hash ^ (hash >> 33u));
}

