	SparkStatus status;
	if ( lane->resident_sequence_slot >=
		pipeline->runtime_limits.resident_sequence_capacity )
		return(0u);
	slot = &pipeline->lease_slots[lane->resident_sequence_slot];
	if ( slot->request_id != lane->request_id ||
